<style>
.hd{max-width:1500px;margin:auto;padding:1rem 0 2rem}.hd-box,.hd-card{background:#fff;border:1px solid #e3e6f0;border-radius:.65rem}.hd-hero{border-left:4px solid #4e73df;padding:1rem 1.25rem;display:flex;justify-content:space-between;align-items:center}.hd-school{display:flex;align-items:center;min-width:0}.hd-logo{width:58px;height:58px;object-fit:contain;border:1px solid #e3e6f0;border-radius:.55rem;padding:4px;margin-right:1rem}.hd-logo-fallback{display:flex;align-items:center;justify-content:center;background:#edf2ff;color:#4e73df;font-size:1.4rem}.hd-title{font-size:1.25rem;font-weight:700;color:#263754;margin:0}.hd-muted{font-size:.78rem;color:#6e7891}.hd-year{background:#f8f9fc;border:1px solid #e3e6f0;border-radius:.5rem;padding:.5rem .75rem;text-align:right;white-space:nowrap}.hd-year strong{display:block;color:#263754}.hd-card{display:block;padding:1rem;height:100%;text-decoration:none!important;transition:.15s}.hd-card:hover{border-color:#b9c7ea;box-shadow:0 .25rem .8rem rgba(38,55,84,.08);transform:translateY(-1px)}.hd-card-head{display:flex;justify-content:space-between;align-items:center}.hd-label{font-size:.76rem;color:#6e7891;font-weight:600}.hd-value{font-size:1.35rem;font-weight:700;color:#263754;margin-top:.65rem}.hd-icon,.hd-list-icon{display:flex;align-items:center;justify-content:center}.hd-icon{width:40px;height:40px;border-radius:.55rem}.hd-primary{background:#edf2ff;color:#4e73df}.hd-success{background:#e8f8ef;color:#1e9e58}.hd-warning{background:#fff7e6;color:#c88700}.hd-danger{background:#fdecec;color:#d94b4b}.hd-head{padding:.85rem 1rem;border-bottom:1px solid #e3e6f0;display:flex;justify-content:space-between;align-items:center}.hd-head h5{font-size:.95rem;font-weight:700;color:#263754;margin:0}.hd-list{padding:.35rem 1rem}.hd-item{display:flex;align-items:center;padding:.72rem 0;border-bottom:1px solid #edf0f5}.hd-item:last-child{border:0}.hd-list-icon{width:34px;height:34px;border-radius:50%;margin-right:.7rem;flex:none}.hd-main{min-width:0;flex:1}.hd-item-title{font-weight:700;color:#344054;font-size:.84rem}.hd-count{font-weight:700;margin-left:.6rem}.hd-empty,.hd-loading{padding:1.5rem;text-align:center;color:#858796}.hd-loading{padding:4rem}.hd-actions{display:flex;flex-wrap:wrap;gap:.55rem}.hd-action{border:1px solid #d8deea;border-radius:.5rem;color:#344054;padding:.55rem .8rem;text-decoration:none!important;font-size:.82rem;font-weight:600}.hd-action:hover{border-color:#4e73df;color:#4e73df}.hd-tabs .nav-link{font-size:.8rem;font-weight:700;color:#6e7891;border:0;border-bottom:2px solid transparent}.hd-tabs .nav-link.active{color:#4e73df;border-bottom-color:#4e73df;background:transparent}.hd-analysis{padding:1rem}.hd-analysis table{font-size:.78rem}.hd-mini{border:1px solid #e3e6f0;border-radius:.5rem;padding:.75rem;background:#f8f9fc;text-align:center;height:100%}.hd-mini strong{display:block;font-size:1.18rem;color:#263754}.hd-chart{border:1px solid #edf0f5;border-radius:.55rem;padding:1rem;background:#fbfcfe}.hd-chart-title{font-size:.78rem;font-weight:700;color:#52617a;margin-bottom:.8rem}.hd-bar{display:grid;grid-template-columns:90px 1fr 70px;gap:.55rem;align-items:center;margin:.62rem 0;font-size:.75rem;color:#6e7891}.hd-track{height:12px;background:#edf0f5;border-radius:7px;overflow:hidden}.hd-fill{height:100%;background:#4e73df;border-radius:7px;min-width:2px}.hd-fill-success{background:#1cc88a}.hd-fill-warning{background:#f6c23e}.hd-fill-danger{background:#e74a3b}.hd-stack{display:flex;height:14px;background:#edf0f5;border-radius:7px;overflow:hidden}.hd-stack span{height:100%}.hd-legend span{font-size:.7rem;margin-right:.8rem}.hd-dot{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:3px}.hd-table-wrap{max-height:330px;overflow:auto}@media(max-width:767px){.hd-logo{width:45px;height:45px}.hd-title{font-size:1.05rem}.hd-year{margin-left:.5rem}.hd-bar{grid-template-columns:70px 1fr 55px}}
</style><style>.hd-profile-tools{border-left:4px solid #4e73df}.hd-profile-tools .hd-actions{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:.8rem}.hd-profile-tools .hd-action{display:flex;align-items:center;padding:1rem;min-height:78px}.hd-tool-icon{width:42px;height:42px;border-radius:.55rem;background:#edf2ff;color:#4e73df;display:flex;align-items:center;justify-content:center;font-size:1.05rem;margin-right:.75rem;flex:none}.hd-tool-text strong{display:block;color:#263754}.hd-tool-text small{display:block;color:#7b8499;font-weight:400;margin-top:.15rem}</style>
<div class="hd"><div id="hd-error" class="alert alert-danger d-none"></div><div id="hd-loading" class="hd-loading"><div class="spinner-border text-primary mb-2"></div><div>Preparando tu panel...</div></div><main id="hd-content" class="d-none">
 <section class="hd-box hd-hero mb-3"><div class="hd-school"><div id="hd-logo"></div><div><h1 id="hd-name" class="hd-title"></h1><div id="hd-welcome" class="hd-muted"></div></div></div><div class="hd-year"><small class="text-muted">Año académico</small><strong id="hd-year"></strong><small id="hd-updated" class="text-muted"></small></div></section>
 <div id="hd-metrics" class="row"></div>
 <div class="row"><div class="col-xl-6 mb-3"><section class="hd-box h-100"><div class="hd-head"><h5><i class="fas fa-tasks text-primary mr-2"></i>Pendientes y alertas</h5><a class="small" href="index.php?page=notifications">Notificaciones</a></div><div id="hd-pending" class="hd-list"></div></section></div><div class="col-xl-6 mb-3"><section class="hd-box h-100"><div class="hd-head"><h5><i class="fas fa-history text-primary mr-2"></i>Actividad reciente</h5></div><div id="hd-activity" class="hd-list"></div></section></div></div>
 <section id="hd-analysis" class="hd-box mb-3 d-none"><div class="hd-head"><h5><i class="fas fa-chart-pie text-primary mr-2"></i>Análisis institucional</h5><small class="text-muted">Solo administración y dirección</small></div><ul class="nav hd-tabs px-3 pt-2"><li><a class="nav-link active" data-toggle="tab" href="#hda-m">Matrícula</a></li><li><a class="nav-link" data-toggle="tab" href="#hda-d">Docentes</a></li><li><a class="nav-link" data-toggle="tab" href="#hda-f">Finanzas</a></li><li><a class="nav-link" data-toggle="tab" href="#hda-a">Asistencia</a></li><li><a class="nav-link" data-toggle="tab" href="#hda-c">Académico</a></li></ul><div class="tab-content hd-analysis"><div id="hda-m" class="tab-pane fade show active"></div><div id="hda-d" class="tab-pane fade"></div><div id="hda-f" class="tab-pane fade"></div><div id="hda-a" class="tab-pane fade"></div><div id="hda-c" class="tab-pane fade"></div></div></section>
 <section id="hd-tools" class="hd-box"><div class="hd-head"><h5 id="hd-tools-title"><i class="fas fa-bolt text-primary mr-2"></i>Acciones rápidas</h5></div><div id="hd-actions" class="p-3 hd-actions"></div></section>
</main></div>
<script>
(function($){
 const e=v=>$('<div>').text(v==null?'':v).html(), money=v=>'S/ '+Number(v||0).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}), tone=t=>['primary','success','warning','danger'].includes(t)?t:'primary';
 const empty=t=>'<div class="hd-empty"><i class="fas fa-check-circle text-success mr-1"></i>'+e(t)+'</div>';
 function bars(rows,labelKey='label',valueKey='value',moneyValues=false,limit=20){rows=(rows||[]).slice(0,limit);let max=Math.max(...rows.map(r=>Number(r[valueKey]||0)),1),h='<div class="hd-chart">';rows.forEach(r=>h+='<div class="hd-bar"><span>'+e(r[labelKey]||'—')+'</span><div class="hd-track"><div class="hd-fill" style="width:'+Math.max(1,Number(r[valueKey]||0)/max*100)+'%"></div></div><strong class="text-right">'+(moneyValues?money(r[valueKey]):e(r[valueKey]))+'</strong></div>');return h+'</div>'}
 function table(headers,rows){let h='<div class="table-responsive hd-table-wrap"><table class="table table-sm table-hover mb-0"><thead class="thead-light"><tr>';headers.forEach(x=>h+='<th'+(x.right?' class="text-right"':'')+'>'+e(x.label)+'</th>');h+='</tr></thead><tbody>';rows.forEach(r=>{h+='<tr>';headers.forEach(x=>h+='<td'+(x.right?' class="text-right font-weight-bold"':'')+'>'+e(r[x.key]??'—')+'</td>');h+='</tr>'});return h+'</tbody></table></div>'}
 function renderAnalysis(a){if(!a||!a.enrollment)return;$('#hd-analysis').removeClass('d-none');let lv=a.enrollment.levels||[],cl=a.enrollment.classrooms||[];$('#hda-m').html('<div class="row"><div class="col-lg-5 mb-3"><div class="hd-chart-title">Estudiantes activos por nivel</div>'+bars(lv)+'</div><div class="col-lg-7 mb-3"><div class="hd-chart-title">Detalle por grado y sección</div>'+table([{label:'Nivel',key:'nivel'},{label:'Grado',key:'grado'},{label:'Sección',key:'seccion'},{label:'Estudiantes',key:'students',right:true}],cl)+'</div></div>');
 let loads=a.teachers.loads||[];$('#hda-d').html('<div class="row"><div class="col-lg-5 mb-3"><div class="row mb-2">'+(a.teachers.summary||[]).map(v=>'<div class="col-6"><div class="hd-mini"><small>'+e(v.label)+'</small><strong>'+e(v.value)+'</strong></div></div>').join('')+'</div><div class="hd-chart-title">Carga académica por docente</div>'+bars(loads,'name','assignments',false,12)+'</div><div class="col-lg-7 mb-3"><div class="hd-chart-title">Detalle de asignaciones</div>'+table([{label:'Docente',key:'name'},{label:'Asignaciones',key:'assignments',right:true}],loads)+'</div></div>');
 let f=a.finance||{},methods=f.methods||[];$('#hda-f').html('<div class="row mb-3"><div class="col-md-4 mb-2"><div class="hd-mini"><small>Recaudado este mes</small><strong>'+money(f.month)+'</strong></div></div><div class="col-md-4 mb-2"><div class="hd-mini"><small>Saldo pendiente</small><strong>'+money(f.pending)+'</strong></div></div><div class="col-md-4 mb-2"><div class="hd-mini"><small>Saldo vencido</small><strong>'+money(f.overdue)+'</strong></div></div></div><div class="hd-chart-title">Recaudación del mes por medio de pago</div>'+bars(methods,'label','value',true));
 let at=a.attendance||[],totalMax=Math.max(...at.map(v=>Number(v.present||0)+Number(v.late||0)+Number(v.absent||0)),1),ah='<div class="hd-legend mb-3"><span><i class="hd-dot bg-success"></i>Presentes</span><span><i class="hd-dot bg-warning"></i>Tardanzas</span><span><i class="hd-dot bg-danger"></i>Ausencias</span></div>';at.forEach(v=>{let p=Number(v.present||0),l=Number(v.late||0),ab=Number(v.absent||0);ah+='<div class="hd-bar"><span>'+e(v.label)+'</span><div class="hd-stack"><span class="bg-success" style="width:'+p/totalMax*100+'%"></span><span class="bg-warning" style="width:'+l/totalMax*100+'%"></span><span class="bg-danger" style="width:'+ab/totalMax*100+'%"></span></div><strong class="text-right">'+(p+l+ab)+'</strong></div>'});$('#hda-a').html('<div class="row"><div class="col-lg-7"><div class="hd-chart-title">Tendencia de los últimos siete días</div><div class="hd-chart">'+ah+'</div></div><div class="col-lg-5">'+table([{label:'Fecha',key:'label'},{label:'P',key:'present',right:true},{label:'T',key:'late',right:true},{label:'A',key:'absent',right:true}],at)+'</div></div>');
 let ac=a.academic||{};$('#hda-c').html('<div class="row"><div class="col-md-4 mb-2"><div class="hd-mini"><small>Asignaciones académicas</small><strong>'+e(ac.courses)+'</strong></div></div><div class="col-md-4 mb-2"><div class="hd-mini"><small>Evaluaciones del año activo</small><strong>'+e(ac.evaluations)+'</strong></div></div><div class="col-md-4 mb-2"><div class="hd-mini"><small>Alertas académicas</small><strong>'+e(ac.alerts)+'</strong></div></div></div>')}
 function render(d){$('#hd-logo').html(d.school.logo_path?'<img class="hd-logo" src="'+e(d.school.logo_path)+'">':'<div class="hd-logo hd-logo-fallback"><i class="fas fa-school"></i></div>');$('#hd-name').text(d.school.name||'Institución educativa');$('#hd-welcome').text('Hola, '+(d.user.name||'Usuario')+' · '+d.user.role);$('#hd-year').text(d.year?d.year.year+' · '+(d.year.status||'Activo'):'Sin año activo');$('#hd-updated').text('Actualizado '+d.updated_at);
 let cards='';(d.metrics||[]).forEach(m=>cards+='<div class="col-xl-3 col-md-4 col-6 mb-3"><a class="hd-card" href="'+e(m.url)+'"><div class="hd-card-head"><span class="hd-label">'+e(m.label)+'</span><span class="hd-icon hd-'+tone(m.tone)+'"><i class="fas '+e(m.icon)+'"></i></span></div><div class="hd-value">'+e(m.value)+'</div></a></div>');$('#hd-metrics').html(cards);let p='';(d.pending||[]).forEach(v=>p+='<a class="hd-item text-decoration-none" href="'+e(v.u)+'"><span class="hd-list-icon hd-'+tone(v.tone)+'"><i class="fas fa-exclamation"></i></span><span class="hd-main"><span class="hd-item-title d-block">'+e(v.t)+'</span><span class="hd-muted">'+e(v.d)+'</span></span><span class="hd-count text-'+tone(v.tone)+'">'+e(v.c)+'</span></a>');$('#hd-pending').html(p||empty('No hay pendientes importantes.'));let act='';(d.activity||[]).forEach(v=>act+='<div class="hd-item"><span class="hd-list-icon hd-primary"><i class="fas '+(v.kind==='payment'?'fa-receipt':'fa-user-check')+'"></i></span><span class="hd-main"><span class="hd-item-title d-block">'+e(v.title)+'</span><span class="hd-muted">'+e(v.detail)+' · '+e(v.event_date)+'</span></span></div>');$('#hd-activity').html(act||empty('Aún no hay actividad reciente.'));let actions='';(d.actions||[]).forEach(v=>actions+='<a class="hd-action" href="'+e(v.url)+'"><i class="fas '+e(v.icon)+' mr-1 text-primary"></i>'+e(v.label)+'</a>');$('#hd-actions').html(actions);renderAnalysis(d.analysis);$('#hd-loading').addClass('d-none');$('#hd-content').removeClass('d-none')}
 $.ajax({url:'home_dashboard_api.php',data:{action:'dashboard',_t:Date.now()},dataType:'json',cache:false}).done(r=>{if(r&&Number(r.status)===1)render(r);else{$('#hd-loading').addClass('d-none');$('#hd-error').removeClass('d-none').text((r&&r.message)||'No se pudo cargar el panel.')}}).fail(x=>{let m='No se pudo cargar el panel de inicio.';try{m=JSON.parse(x.responseText).message||m}catch(z){}$('#hd-loading').addClass('d-none');$('#hd-error').removeClass('d-none').text(m)})
})(jQuery);
</script>
<script>
(function($){$(document).ajaxSuccess(function(_,xhr,settings,data){if(!settings.url||settings.url.indexOf('home_dashboard_api.php')<0||!data||!data.user||data.user.role==='Administrador')return;$('#hd-metrics').addClass('d-none');$('#hd-pending').closest('.row').addClass('d-none');$('#hd-analysis').addClass('d-none');if(data.user.role!=='Director')return;let descriptions={'Estudiantes':'Gestiona estudiantes activos y su información.','Docentes':'Administra docentes y sus estados.','Gestión académica':'Organiza áreas, cursos y asignaciones.','Años académicos':'Consulta y administra periodos escolares.','Pagos y caja':'Registra pagos y revisa operaciones.','Asistencia':'Gestiona la asistencia institucional.','Reportes':'Consulta los reportes disponibles.','Notificaciones':'Revisa solicitudes y alertas.','Mis cursos':'Consulta los cursos, grados y secciones que tiene asignados.','Registrar notas':'Crea evaluaciones y registra calificaciones como docente.','Competencias':'Administra las competencias de sus cursos.','Reporte de notas':'Consulta y exporta resultados académicos.'},html='';(data.actions||[]).forEach(a=>{let safe=v=>$('<div>').text(v).html();html+='<a class="hd-action" href="'+safe(a.url)+'"><span class="hd-tool-icon"><i class="fas '+safe(a.icon)+'"></i></span><span class="hd-tool-text"><strong>'+safe(a.label)+'</strong><small>'+safe(descriptions[a.label]||'Abrir esta herramienta.')+'</small></span></a>'});$('#hd-tools').addClass('hd-profile-tools mb-3').insertAfter('#hd-metrics');$('#hd-tools-title').html('<i class="fas fa-th-large text-primary mr-2"></i>Herramientas de Director');$('#hd-actions').html(html)})})(jQuery);
</script>
<script>
(function($){$(document).ajaxSuccess(function(_,xhr,settings,data){if(!settings.url||settings.url.indexOf('home_dashboard_api.php')<0||!data||!data.user)return;let role=data.user.role||'',isInstitutional=role==='Administrador'||role==='Director';if(isInstitutional)return;let descriptions={Docente:{'Mis cursos':'Consulta cursos, grados y secciones asignados.','Registrar notas':'Crea evaluaciones y registra calificaciones.','Competencias':'Administra competencias de tus cursos.','Reporte de notas':'Consulta y exporta resultados académicos.'},Auxiliar:{'Tomar asistencia':'Registra y revisa la asistencia del día.','Reglas':'Consulta horarios y reglas de asistencia.','Reporte':'Analiza asistencias, tardanzas y ausencias.','Notificaciones':'Revisa el resultado de tus solicitudes.'},Estudiante:{'Mis notas':'Consulta tus calificaciones y competencias.','Mi asistencia':'Revisa tu historial de asistencia.','Mis pagos':'Consulta los pagos realizados.','Mis deudas':'Revisa saldos y fechas de vencimiento.'}};let html='';(data.actions||[]).forEach(a=>{let detail=(descriptions[role]||{})[a.label]||'Abrir esta herramienta.';html+='<a class="hd-action" href="'+$('<div>').text(a.url).html()+'"><span class="hd-tool-icon"><i class="fas '+$('<div>').text(a.icon).html()+'"></i></span><span class="hd-tool-text"><strong>'+$('<div>').text(a.label).html()+'</strong><small>'+$('<div>').text(detail).html()+'</small></span></a>'});$('#hd-tools').addClass('hd-profile-tools mb-3').insertAfter('#hd-metrics');$('#hd-tools-title').html('<i class="fas fa-th-large text-primary mr-2"></i>Herramientas de '+$('<div>').text(role).html());$('#hd-actions').html(html)})})(jQuery);
</script>
